void add_edge(int from, int to, ll cap) {
    edges[edge_cnt] = (Edge){to, head[from], cap};
    head[from] = edge_cnt++;
    edges[edge_cnt] = (Edge){from, head[to], 0};
    head[to] = edge_cnt++;
}

int bfs(int s, int t) {
    memset(level, -1, sizeof(level));
    int q[MAXN * 2 + 5], front = 0, back = 0;
    level[s] = 0;
    q[back++] = s;
    while (front < back) {
        int v = q[front++];
        for (int i = head[v]; i != -1; i = edges[i].next) {
            if (edges[i].cap > 0 && level[edges[i].to] < 0) {
                level[edges[i].to] = level[v] + 1;
                q[back++] = edges[i].to;
            }
        }
    }
    return level[t] >= 0;
}

ll dfs(int v, int t, ll f) {
    if (v == t) return f;
    for (int &i = iter[v]; i != -1; i = edges[i].next) {
        if (edges[i].cap > 0 && level[v] < level[edges[i].to]) {
            ll d = dfs(edges[i].to, t, f < edges[i].cap ? f : edges[i].cap);
            if (d > 0) {
                edges[i].cap -= d;
                edges[i ^ 1].cap += d;
                return d;
            }
        }
    }
    return 0;
}

ll max_flow(int s, int t) {
    ll flow = 0;
    while (bfs(s, t)) {
        memcpy(iter, head, sizeof(int) * (N * 2 + 5));
        ll f;
        while ((f = dfs(s, t, LLONG_MAX)) > 0) {
            flow += f;
        }
    }
    return flow;
}

