const long long INF = 1e18;

struct Edge {
    int to, rev;
    long long cap;
};

class Dinic {
public:
    vector<vector<Edge>> graph;
    vector<int> level, it;
    int N;

    Dinic(int n) {
        N = n;
        graph.resize(N);
        level.resize(N);
        it.resize(N);
    }

    void add_edge(int from, int to, long long cap) {
        graph[from].push_back({to, (int)graph[to].size(), cap});
        graph[to].push_back({from, (int)graph[from].size() - 1, 0});
    }

    bool bfs(int s, int t) {
        fill(level.begin(), level.end(), -1);
        queue<int> q;
        level[s] = 0;
        q.push(s);
        while (!q.empty()) {
            int v = q.front(); q.pop();
            for (auto &e : graph[v]) {
                if (e.cap > 0 && level[e.to] < 0) {
                    level[e.to] = level[v] + 1;
                    q.push(e.to);
                }
            }
        }
        return level[t] >= 0;
    }

    long long dfs(int v, int t, long long f) {
        if (v == t) return f;
        for (int &i = it[v]; i < (int)graph[v].size(); i++) {
            Edge &e = graph[v][i];
            if (e.cap > 0 && level[v] < level[e.to]) {
                long long d = dfs(e.to, t, min(f, e.cap));
                if (d > 0) {
                    e.cap -= d;
                    graph[e.to][e.rev].cap += d;
                    return d;
                }
            }
        }
        return 0;
    }

    long long max_flow(int s, int t) {
        long long flow = 0;
        while (bfs(s, t)) {
            fill(it.begin(), it.end(), 0);
            long long f;
            while ((f = dfs(s, t, INF)) > 0) {
                flow += f;
            }
        }
        return flow;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;
    string U;
    cin >> U;
    vector<long long> A(N);
    for (int i = 0; i < N; i++) cin >> A[i];

    // source: N, sink: N+1
    int S = N, T = N + 1;
    Dinic dinic(N + 2);

    long long total = 0;

    for (int i = 0; i < N; i++) {
        if (U[i] == 'L') {
            // initially left: choose to stay left (0 cost) or turn to right (cost A[i])
            // cut edge from source: if not cut -> stays left, cut -> turns right
            dinic.add_edge(S, i, A[i]);
            // edge to sink with INF to force orientation? Actually we need:
            // if cut source edge, ghost turns right (cost A[i] incurred)
            // if cut sink edge, ghost stays left (cost 0 incurred)
            dinic.add_edge(i, T, 0); // will be adjusted for constraints
        } else {
            // initially right: stay right (0 cost) or turn to left (cost A[i])
            dinic.add_edge(S, i, 0);
            dinic.add_edge(i, T, A[i]);
        }
    }

    // For constraints: if S_i scared of T_i
    // If S_i faces T_i -> cost B_i
    // We add edge to enforce that if both are in certain states, we must cut.
    // Model: L ghost (i) has source side = left, sink side = right
    // R ghost (j) has source side = left, sink side = right
    // They face each other when i is right and j is left.
    // That is i on sink side, j on source side.
    // So add edge from i to j with capacity B_i (or B_i? problem says B_i per constraint)
    // Actually each constraint has its own B_i, so we use B_i.
    for (int idx = 0; idx < M; idx++) {
        int s, t;
        long long b;
        cin >> s >> t >> b;
        s--; t--;
        // if s faces t: s is right (sink side) and t is left (source side)
        // add edge s -> t with capacity b
        dinic.add_edge(s, t, b);
        total += b; // for potential min cut reasoning
    }

    long long min_cut = dinic.max_flow(S, T);
    cout << min_cut << "\n";

    return 0;
}

