using ll = long long;
const ll INF = (1LL << 62);

struct Edge {
    int to, rev;
    ll cap;
};

struct Dinic {
    int n;
    vector<vector<Edge>> g;
    vector<int> level, it;

    Dinic(int n) : n(n), g(n), level(n), it(n) {}

    void addEdge(int fr, int to, ll cap) {
        Edge a{to, (int)g[to].size(), cap};
        Edge b{fr, (int)g[fr].size(), 0};
        g[fr].push_back(a);
        g[to].push_back(b);
    }

    bool bfs(int s, int t) {
        fill(level.begin(), level.end(), -1);
        queue<int> q;
        level[s] = 0;
        q.push(s);
        while (!q.empty()) {
            int v = q.front();
            q.pop();
            for (const auto &e : g[v]) {
                if (e.cap > 0 && level[e.to] < 0) {
                    level[e.to] = level[v] + 1;
                    q.push(e.to);
                }
            }
        }
        return level[t] >= 0;
    }

    ll dfs(int v, int t, ll f) {
        if (v == t) return f;
        for (int &i = it[v]; i < (int)g[v].size(); i++) {
            Edge &e = g[v][i];
            if (e.cap > 0 && level[v] < level[e.to]) {
                ll d = dfs(e.to, t, min(f, e.cap));
                if (d > 0) {
                    e.cap -= d;
                    g[e.to][e.rev].cap += d;
                    return d;
                }
            }
        }
        return 0;
    }

    ll maxflow(int s, int t) {
        ll flow = 0;
        while (bfs(s, t)) {
            fill(it.begin(), it.end(), 0);
            while (true) {
                ll f = dfs(s, t, INF);
                if (!f) break;
                flow += f;
            }
        }
        return flow;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;

    string U;
    cin >> U;

    vector<ll> A(N + 1);
    for (int i = 1; i <= N; i++) cin >> A[i];

    int S = 0, T = N + 1;
    Dinic mf(N + 2);

    // x_i = 0 means final direction is L
    // x_i = 1 means final direction is R
    //
    // Turning cost:
    // if initial is L: cost A_i when x_i = 1
    // if initial is R: cost A_i when x_i = 0
    //
    // Encode unary costs with source/sink edges:
    // cost(0)=a, cost(1)=b  => add S->i (b), i->T (a)
    for (int i = 1; i <= N; i++) {
        ll cost0, cost1;
        if (U[i - 1] == 'L') {
            cost0 = 0;
            cost1 = A[i];
        } else {
            cost0 = A[i];
            cost1 = 0;
        }
        mf.addEdge(S, i, cost1);
        mf.addEdge(i, T, cost0);
    }

    // Constraint: S_i is scared of T_i.
    // If S_i faces T_i in final state, add B_i.
    //
    // Since ghosts are in a line:
    // if s < t, then s faces t iff x_s = R (1)
    // if s > t, then s faces t iff x_s = L (0)
    //
    // So each constraint is just unary on x_s.
    for (int i = 0; i < M; i++) {
        int s, t;
        ll b;
        cin >> s >> t >> b;

        if (s < t) {
            // penalty when x_s = 1
            mf.addEdge(S, s, b);
        } else {
            // penalty when x_s = 0
            mf.addEdge(s, T, b);
        }
    }

    cout << mf.maxflow(S, T) << '\n';
    return 0;
}

import sys
from collections import deque

input = sys.stdin.readline

class MaxFlow:
    def __init__(self, n):
        self.n = n
        self.adj = [[] for _ in range(n)]

    def add_edge(self, fr, to, cap):
        self.adj[fr].append([to, cap, len(self.adj[to])])
        self.adj[to].append([fr, 0, len(self.adj[fr]) - 1])

    def bfs(self, s, t, level):
        for i in range(self.n):
            level[i] = -1
        q = deque()
        level[s] = 0
        q.append(s)
        while q:
            v = q.popleft()
            for to, cap, rev in self.adj[v]:
                if cap > 0 and level[to] < 0:
                    level[to] = level[v] + 1
                    q.append(to)
        return level[t] >= 0

    def dfs(self, v, t, f, level, it):
        if v == t:
            return f
        for i in range(it[v], len(self.adj[v])):
            it[v] = i
            to, cap, rev = self.adj[v][i]
            if cap > 0 and level[v] + 1 == level[to]:
                ret = self.dfs(to, t, min(f, cap), level, it)
                if ret > 0:
                    self.adj[v][i][1] -= ret
                    self.adj[to][rev][1] += ret
                    return ret
        return 0

    def max_flow(self, s, t):
        flow = 0
        INF = 10**18
        level = [-1] * self.n
        while self.bfs(s, t, level):
            it = [0] * self.n
            while True:
                f = self.dfs(s, t, INF, level, it)
                if f == 0:
                    break
                flow += f
        return flow

def solve():
    N, M = map(int, input().split())
    U = input().strip()
    A = list(map(int, input().split()))
    # nodes: 0..N-1 ghosts, source = N, sink = N+1
    SRC = N
    SNK = N + 1
    mf = MaxFlow(N + 2)
    INF = 10**18
    for i in range(N):
        if U[i] == 'L':
            # initially left, turning costs A[i] to face right
            mf.add_edge(SRC, i, A[i])
            # facing left costs 0, so no edge to sink
        else: # 'R'
            mf.add_edge(i, SNK, A[i])
    for _ in range(M):
        s, t, b = map(int, input().split())
        s -= 1
        t -= 1
        if s < t:
            # s right, t left -> cost b
            mf.add_edge(s, t, b)
        else:
            # t right, s left -> cost b
            mf.add_edge(t, s, b)
    ans = mf.max_flow(SRC, SNK)
    print(ans)

if __name__ == "__main__":
    solve()

