        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int N = Integer.parseInt(st.nextToken());
        int M = Integer.parseInt(st.nextToken());
        String U = br.readLine().trim();

        int[] A = new int[N];
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < N; i++) {
            A[i] = Integer.parseInt(st.nextToken());
        }

        // Build flow network: minimum cut = minimum total fear
        // Each ghost i has two states: facing left (L) or right (R)
        // We create nodes: source = 0, sink = 2*N+1
        // For each ghost i: node i (state L) and node i+N (state R)
        nodeCount = 2 * N + 2;
        int source = 0;
        int sink = 2 * N + 1;

        graph = new ArrayList[nodeCount];
        for (int i = 0; i < nodeCount; i++) {
            graph[i] = new ArrayList<>();
        }

        // Source to initial direction: if initially L, cut edge from source to L state = 0,
        // but we need to ensure we pay A_i if we flip.
        // Classic construction: 
        //   - source -> L_i with capacity A_i (pay if we cut this, meaning we choose R)
        //   - R_i -> sink with capacity A_i (pay if we cut this, meaning we choose L)
        //   - For constraint: if S_i is scared of T_i, we add edge L_S -> R_T with capacity B_i
        //     meaning if S is L and T is R, they face each other and we pay B_i.
        //   - Also need to handle when S is R and T is L: add edge L_T -> R_S with capacity B_i
        //     (since if T is L and S is R they face each other).
        //   - Additionally, if initial direction is L, we want to force that choosing L costs 0,
        //     choosing R costs A_i. So source->L_i = A_i, R_i->sink = 0? Wait, need to think.
        //
        // Actually standard reduction for "minimum cut with two choices":
        // For each ghost i:
        //   - if initially L: we want cut edge (source, L_i) = A_i, and edge (R_i, sink) = INF
        //     so that if we cut source-L_i we pay A_i (flip to R), if we don't cut it we stay L.
        //     But we cannot cut R_i-sink because it's INF.
        //   - if initially R: edge (source, L_i) = INF, edge (R_i, sink) = A_i.
        // For constraint (S, T, B):
        //   - If S faces T: meaning S is L and T is R, then we add edge L_S -> R_T with capacity B.
        //   - Also if S is R and T is L, then add edge L_T -> R_S with capacity B.
        //   - But note: in the cut, if S is L (source side) and T is R (sink side), then edge crosses cut and we pay B.
        //     So we need both directed edges? Actually we just need one directed edge that goes from L side to R side.
        //     For S scared of T: if S is L and T is R, they face each other. So add edge L_S -> R_T with capacity B.
        //     For the reverse case (S is R and T is L): add edge L_T -> R_S with capacity B.
        //     This ensures that whenever the two ghosts face each other, the cut includes that edge.
        //

        // Build edges
        for (int i = 0; i < N; i++) {
            int L = i + 1;
            int R = i + 1 + N;
            if (U.charAt(i) == 'L') {
                addEdge(source, L, A[i]);
                addEdge(R, sink, INF);
            } else { // 'R'
                addEdge(source, L, INF);
                addEdge(R, sink, A[i]);
            }
        }

        for (int k = 0; k < M; k++) {
            st = new StringTokenizer(br.readLine());
            int S = Integer.parseInt(st.nextToken()) - 1;
            int T = Integer.parseInt(st.nextToken()) - 1;
            int B = Integer.parseInt(st.nextToken());

            int L_S = S + 1;
            int R_S = S + 1 + N;
            int L_T = T + 1;
            int R_T = T + 1 + N;

            // S is L and T is R -> they face each other
            addEdge(L_S, R_T, B);
            // S is R and T is L -> they face each other
            addEdge(L_T, R_S, B);
        }

        long minFear = dinic(source, sink);
        System.out.println(minFear);
    }

    static void addEdge(int from, int to, long cap) {
        graph[from].add(new Edge(to, cap, graph[to].size()));
        graph[to].add(new Edge(from, 0, graph[from].size() - 1));
    }

    static long dinic(int s, int t) {
        long flow = 0;
        int[] level = new int[nodeCount];
        int[] it = new int[nodeCount];

        while (true) {
            Arrays.fill(level, -1);
            Queue<Integer> q = new LinkedList<>();
            level[s] = 0;
            q.add(s);
            while (!q.isEmpty()) {
                int v = q.poll();
                for (Edge e : graph[v]) {
                    if (e.cap > 0 && level[e.to] < 0) {
                        level[e.to] = level[v] + 1;
                        q.add(e.to);
                    }
                }
            }
            if (level[t] < 0) break;

            Arrays.fill(it, 0);
            long f;
            while ((f = dfs(s, t, INF, level, it)) > 0) {
                flow += f;
            }
        }
        return flow;
    }

    static long dfs(int v, int t, long f, int[] level, int[] it) {
        if (v == t) return f;
        for (; it[v] < graph[v].size(); it[v]++) {
            Edge e = graph[v].get(it[v]);
            if (e.cap > 0 && level[v] < level[e.to]) {
                long d = dfs(e.to, t, Math.min(f, e.cap), level, it);
                if (d > 0) {
                    e.cap -= d;
                    graph[e.to].get(e.rev).cap += d;
                    return d;
                }
            }
        }
        return 0;
    }

    static class Edge {
        int to;
        long cap;
        int rev;

        Edge(int to, long cap, int rev) {
            this.to = to;
            this.cap = cap;
            this.rev = rev;
        }
    }
}

import java.util.*;
