public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int N = Integer.parseInt(br.readLine().trim());
        long[] A = new long[N+1];
        String[] dirs = new String[N+1];
        StringTokenizer st = new StringTokenizer(br.readLine());
        for (int i = 1; i <= N; i++) A[i] = Long.parseLong(st.nextToken());
        st = new StringTokenizer(br.readLine());
        for (int i = 1; i <= N; i++) dirs[i] = st.nextToken();

        int M = Integer.parseInt(br.readLine().trim());
        long[] costKeep = new long[N+1];
        long[] costFlip = new long[N+1];

        for (int j = 0; j < M; j++) {
            st = new StringTokenizer(br.readLine());
            int S = Integer.parseInt(st.nextToken());
            int T = Integer.parseInt(st.nextToken());
            long B = Long.parseLong(st.nextToken());

            // Bad if S faces T
            // S faces T if: S < T and S faces Right, or S > T and S faces Left
            String badDir = (S < T) ? "R" : "L";
            // Keep: S has dirs[S]
            if (dirs[S].equals(badDir)) costKeep[S] += B;
            // Flip: S has opposite of dirs[S]
            String flipped = dirs[S].equals("L") ? "R" : "L";
            if (flipped.equals(badDir)) costFlip[S] += B;
        }

        long ans = 0;
        for (int i = 1; i <= N; i++) {
            ans += Math.min(costKeep[i], A[i] + costFlip[i]);
        }
        System.out.println(ans);
    }
}

import java.io.*;
import java.util.*;

/*
We model each ghost's final direction as a binary variable x_i:
x_i = 0 -> final direction is Left
x_i = 1 -> final direction is Right

Turning cost:
- if initial is L, cost A_i when x_i = 1
- if initial is R, cost A_i when x_i = 0

Constraint: ghost s is scared of ghost t.
If in final state, s faces t, then add cost B.
Since ghosts are in a line:
- if s < t, then s faces t iff s looks right => x_s = 1
- if s > t, then s faces t iff s looks left  => x_s = 0
So each fear constraint adds a unary cost on x_s only.

Thus total cost is completely separable per ghost.
For each ghost i, compute:
costLeft[i], costRight[i]
including turning cost and all fear constraints involving i as source.
Answer = sum min(costLeft[i], costRight[i]).
*/

public class Main {
    // Fast scanner
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            if (c == -1) return null;
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int N = fs.nextInt();
        int M = fs.nextInt();
        String U = fs.next();

        long[] leftCost = new long[N];
        long[] rightCost = new long[N];

        for (int i = 0; i < N; i++) {
            long a = fs.nextLong();
            if (U.charAt(i) == 'L') {
                leftCost[i] += 0;
                rightCost[i] += a;
            } else {
                leftCost[i] += a;
                rightCost[i] += 0;
            }
        }

        for (int i = 0; i < M; i++) {
            int s = fs.nextInt() - 1;
            int t = fs.nextInt() - 1;
            long b = fs.nextLong();

            if (s < t) {
                // s faces t iff s looks right
                rightCost[s] += b;
            } else if (s > t) {
                // s faces t iff s looks left
                leftCost[s] += b;
            }
            // s == t should not normally occur; if it does, facing oneself is irrelevant here.
        }

        long ans = 0;
        for (int i = 0; i < N; i++) {
            ans += Math.min(leftCost[i], rightCost[i]);
        }

        System.out.println(ans);
    }
}
